import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Проблемы игрока","description":"","frontmatter":{"pageId":"players/troubleshooting","contentRevision":1},"headers":[],"relativePath":"ru/players/troubleshooting.md","filePath":"ru/players/troubleshooting.md"}'),d={name:"ru/players/troubleshooting.md"};function i(l,t,s,n,h,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="проблемы-игрока" tabindex="-1">Проблемы игрока <a class="header-anchor" href="#проблемы-игрока" aria-label="Permalink to &quot;Проблемы игрока&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Симптом</th><th>Что проверить</th></tr></thead><tbody><tr><td>Нет Мультиплеера</td><td>Версии игры/Harmony, список модов, вложенные папки</td></tr><tr><td>Отказ сертификата</td><td>Адрес, время системы, подтверждённый pin; не отключать TLS</td></tr><tr><td>Различия модов</td><td>Порядок, версии, hash, настройки; применить пакет с закрытой игрой</td></tr><tr><td>Вещи не отправляются</td><td>Консоль/маяки, доступность предметов, долг, угроза, заморозка</td></tr><tr><td>Live завис после обрыва</td><td>Дождаться переподключения, проверить связь хозяина, запросить снимок</td></tr><tr><td>Coop занят</td><td>Один активный партнёр, хозяин дома онлайн, назначены допустимые пешки</td></tr></tbody></table><p>Сначала сохрани свидетельства ошибки: точное сообщение, время, сервер, действие и id операции. Экспорт диагностики создаёт локальный ZIP; проверь содержимое перед самостоятельной отправкой администратору.</p><h3 id="получить-локальныи-отчет" tabindex="-1">Получить локальный отчёт <a class="header-anchor" href="#получить-локальныи-отчет" aria-label="Permalink to &quot;Получить локальный отчёт&quot;">​</a></h3><ol><li>Открой <strong>Мультиплеер → Диагностика</strong> в списке серверов или диагностику из игрового оверлея Rimlink. Снимок делается при открытии; закрой и открой окно для обновления.</li><li>Проверь предпросмотр и нажми <strong>Сохранить локальный ZIP</strong>. Путь показывается до сохранения, имя файла — после. Отчёт находится в <code>Rimlink/Diagnostics</code> внутри каталога save-data игры; ZIP содержит diagnostics.json и ограниченный events.log без свободного текста сообщений.</li><li>Для Windows стандартная папка профиля — <code>%USERPROFILE%/AppData/LocalLow/Ludeon Studios/RimWorld by Ludeon Studios</code>; игровой журнал отдельно лежит в <code>Logs/Player.log</code>. При собственном -savedatafolder ищи данные там. Отчёт не включает этот журнал; согласуй отдельно безопасную выдержку, если она нужна.</li></ol><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Диагностика не загружается автоматически и не включает Player.log/произвольные логи. Логи игры могут содержать личные данные: не публикуй целиком. Не удаляй восстановительные журналы и не принимай неизвестные сертификаты.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./connect">Подключение и вход</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li><li><a href="./../admins/troubleshooting">Проблемы администратора</a></li></ul>',11)])])}const m=a(d,[["render",i]]);export{p as __pageData,m as default};
